-- CHAMBA 038 — Aislamiento técnico: RLS en jobs/assignments + RPC acotados-- Objetivo: un técnico solo lee jobs open (radar) o los suyos asignados/postulados.-- Sin pilot_anon_assignments_select (USING true) ni get_worker_assignments abierto a anon.SET statement_timeout = '120s';-- ── Asegurar RLS activo ─────────────────────────────────────────────────────ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;ALTER TABLE jobs ENABLE ROW LEVEL SECURITY;ALTER TABLE job_assignments ENABLE ROW LEVEL SECURITY;-- ── Helpers (idempotente) ───────────────────────────────────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS fn_get_my_role CASCADE;CREATE OR REPLACE FUNCTION fn_get_my_role()RETURNS TEXTLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT role::TEXT FROM profiles WHERE id = auth.uid();$$;CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS fn_is_approved CASCADE;CREATE OR REPLACE FUNCTION fn_is_approved()RETURNS BOOLEANLANGUAGE sqlSTABLESECURITY DEFINERSET search_path = publicAS $$  SELECT COALESCE(is_approved, FALSE) FROM profiles WHERE id = auth.uid();$$;-- ── Quitar políticas piloto permisivas (añadidas fuera de migraciones) ───────DROP POLICY IF EXISTS "pilot_anon_jobs_select" ON jobs;DROP POLICY IF EXISTS "pilot_anon_jobs_insert" ON jobs;DROP POLICY IF EXISTS "pilot_anon_jobs_update" ON jobs;-- Cliente: políticas canónicas (pueden faltar si solo existían pilot_anon_*)DROP POLICY IF EXISTS "jobs: client insert own" ON jobs;CREATE POLICY "jobs: client insert own"  ON jobs FOR INSERT  TO authenticated  WITH CHECK (    created_by = auth.uid()    AND EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text IN ('client', 'admin')    )  );DROP POLICY IF EXISTS "jobs: client select own" ON jobs;CREATE POLICY "jobs: client select own"  ON jobs FOR SELECT  TO authenticated  USING (created_by = auth.uid());-- ── jobs: reemplazar lectura amplia de técnicos ─────────────────────────────DROP POLICY IF EXISTS "jobs: approved worker read" ON jobs;DROP POLICY IF EXISTS "jobs: worker read scoped" ON jobs;CREATE POLICY "jobs: worker read scoped"  ON jobs FOR SELECT  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid()        AND p.role::text = 'worker'        AND COALESCE(p.is_approved, FALSE) = TRUE    )    AND (      status::text = 'open'      OR assigned_worker_id = auth.uid()      OR EXISTS (        SELECT 1 FROM job_assignments ja        WHERE ja.job_id = jobs.id          AND ja.worker_id = auth.uid()      )    )  );-- ── job_assignments: técnico solo las suyas ─────────────────────────────────DROP POLICY IF EXISTS "assignments: worker select own" ON job_assignments;CREATE POLICY "assignments: worker select own"  ON job_assignments FOR SELECT  TO authenticated  USING (worker_id = auth.uid());DROP POLICY IF EXISTS "assignments: admin all" ON job_assignments;CREATE POLICY "assignments: admin all"  ON job_assignments FOR ALL  TO authenticated  USING (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    )  )  WITH CHECK (    EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    )  );-- Quitar lectura anónima total (fuga de postulaciones de todos los técnicos)DROP POLICY IF EXISTS "pilot_anon_assignments_select" ON job_assignments;-- ── RPC: agenda del técnico — solo propio worker o admin ────────────────────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_worker_assignments CASCADE;CREATE OR REPLACE FUNCTION get_worker_assignments(p_worker_id UUID)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_result JSONB;BEGIN  IF p_worker_id IS NULL THEN    RETURN '[]'::jsonb;  END IF;  IF auth.uid() IS NULL THEN    RETURN '[]'::jsonb;  END IF;  IF auth.uid() <> p_worker_id THEN    IF NOT EXISTS (      SELECT 1 FROM profiles p      WHERE p.id = auth.uid() AND p.role::text = 'admin'    ) THEN      RETURN '[]'::jsonb;    END IF;  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_worker_id AND p.role::text = 'worker'  ) THEN    RETURN '[]'::jsonb;  END IF;  SELECT COALESCE(    jsonb_agg(      jsonb_build_object(        'id', ja.id,        'job_id', ja.job_id,        'worker_id', ja.worker_id,        'assigned_at', ja.assigned_at,        'completed_at', ja.completed_at,        'payment_status', ja.payment_status,        'payment_intent_id', ja.payment_intent_id,        'selection_status', ja.selection_status,        'job', to_jsonb(j.*)      )      ORDER BY ja.assigned_at DESC    ),    '[]'::jsonb  )  INTO v_result  FROM job_assignments ja  JOIN jobs j ON j.id = ja.job_id  WHERE ja.worker_id = p_worker_id;  RETURN v_result;END;$$;GRANT EXECUTE ON FUNCTION get_worker_assignments(UUID) TO authenticated;-- ── RPC: radar — solo jobs open (sin filtrar taken/in_progress ajenos) ──────CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_worker_open_jobs_feed CASCADE;CREATE OR REPLACE FUNCTION get_worker_open_jobs_feed(  p_worker_id    UUID,  p_status       TEXT DEFAULT 'open',  p_categories   TEXT[] DEFAULT NULL,  p_limit        INT DEFAULT 20,  p_offset       INT DEFAULT 0)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_rows JSONB;  v_total BIGINT;  v_status TEXT;BEGIN  IF p_worker_id IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Trabajador requerido');  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_worker_id      AND p.role::text = 'worker'      AND COALESCE(p.is_approved, FALSE) = TRUE  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Colaborador no aprobado');  END IF;  v_status := COALESCE(NULLIF(trim(p_status), ''), 'open');  -- Este RPC es exclusivamente el radar de solicitudes abiertas  IF v_status <> 'open' THEN    RETURN jsonb_build_object(      'success', false,      'error', 'Solo feed de trabajos abiertos (open)'    );  END IF;  SELECT COUNT(*) INTO v_total  FROM jobs j  WHERE j.status::text = 'open'    AND (      p_categories IS NULL      OR cardinality(p_categories) = 0      OR j.category::text = ANY (p_categories)    );  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb) INTO v_rows  FROM (    SELECT j.*    FROM jobs j    WHERE j.status::text = 'open'      AND (        p_categories IS NULL        OR cardinality(p_categories) = 0        OR j.category::text = ANY (p_categories)      )    ORDER BY j.created_at DESC    LIMIT GREATEST(p_limit, 1)    OFFSET GREATEST(p_offset, 0)  ) t;  RETURN jsonb_build_object(    'success', true,    'jobs', v_rows,    'count', v_total  );END;$$;GRANT EXECUTE ON FUNCTION get_worker_open_jobs_feed(UUID, TEXT, TEXT[], INT, INT) TO authenticated, anon;-- get_open_jobs_feed (JWT): también acotar a openCREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS get_open_jobs_feed CASCADE;CREATE OR REPLACE FUNCTION get_open_jobs_feed(  p_status       TEXT DEFAULT 'open',  p_categories   TEXT[] DEFAULT NULL,  p_limit        INT DEFAULT 20,  p_offset       INT DEFAULT 0)RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_rows JSONB;  v_total BIGINT;  v_status TEXT;BEGIN  IF auth.uid() IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Sesión requerida');  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = auth.uid()      AND (        (p.role::text = 'worker' AND COALESCE(p.is_approved, FALSE) = TRUE)        OR p.role::text = 'admin'      )  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Colaborador no aprobado');  END IF;  v_status := COALESCE(NULLIF(trim(p_status), ''), 'open');  IF v_status <> 'open' THEN    RETURN jsonb_build_object('success', false, 'error', 'Solo feed de trabajos abiertos (open)');  END IF;  SELECT COUNT(*) INTO v_total  FROM jobs j  WHERE j.status::text = 'open'    AND (      p_categories IS NULL      OR cardinality(p_categories) = 0      OR j.category::text = ANY (p_categories)    );  SELECT COALESCE(jsonb_agg(to_jsonb(t)), '[]'::jsonb) INTO v_rows  FROM (    SELECT j.*    FROM jobs j    WHERE j.status::text = 'open'      AND (        p_categories IS NULL        OR cardinality(p_categories) = 0        OR j.category::text = ANY (p_categories)      )    ORDER BY j.created_at DESC    LIMIT GREATEST(p_limit, 1)    OFFSET GREATEST(p_offset, 0)  ) t;  RETURN jsonb_build_object(    'success', true,    'jobs', v_rows,    'count', v_total  );END;$$;GRANT EXECUTE ON FUNCTION get_open_jobs_feed(TEXT, TEXT[], INT, INT) TO authenticated;